import java.util.*;

class MKAverage {
  private final int m, k;
  private final Deque<Integer> queue = new ArrayDeque<>();
  private final TreeMap<Integer, Integer> low = new TreeMap<>(),
      middle = new TreeMap<>(),
      high = new TreeMap<>();
  private int lowSize, middleSize, highSize;
  private long middleSum;

  public MKAverage(int m, int k) {
    this.m = m;
    this.k = k;
  }

  public void addElement(int num) {
    queue.addLast(num);
    add(middle, num);
    middleSize++;
    middleSum += num;
    rebalance();
    if (queue.size() > m) {
      int old = queue.removeFirst();
      removeValue(old);
      rebalance();
    }
  }

  public int calculateMKAverage() {
    return queue.size() < m ? -1 : (int) (middleSum / (m - 2L * k));
  }

  private void removeValue(int x) {
    if (low.containsKey(x)) {
      remove(low, x);
      lowSize--;
    } else if (high.containsKey(x)) {
      remove(high, x);
      highSize--;
    } else {
      remove(middle, x);
      middleSize--;
      middleSum -= x;
    }
  }

  private void rebalance() {
    while (lowSize > k) {
      int x = low.lastKey();
      remove(low, x);
      lowSize--;
      add(middle, x);
      middleSize++;
      middleSum += x;
    }
    while (highSize > k) {
      int x = high.firstKey();
      remove(high, x);
      highSize--;
      add(middle, x);
      middleSize++;
      middleSum += x;
    }
    while (lowSize < k && middleSize > 0) {
      int x = middle.firstKey();
      remove(middle, x);
      middleSize--;
      middleSum -= x;
      add(low, x);
      lowSize++;
    }
    while (highSize < k && middleSize > 0) {
      int x = middle.lastKey();
      remove(middle, x);
      middleSize--;
      middleSum -= x;
      add(high, x);
      highSize++;
    }
    while (lowSize > 0 && middleSize > 0 && low.lastKey() > middle.firstKey()) {
      int a = low.lastKey(), b = middle.firstKey();
      remove(low, a);
      remove(middle, b);
      add(low, b);
      add(middle, a);
      middleSum += a - b;
    }
    while (highSize > 0 && middleSize > 0 && middle.lastKey() > high.firstKey()) {
      int a = middle.lastKey(), b = high.firstKey();
      remove(middle, a);
      remove(high, b);
      add(middle, b);
      add(high, a);
      middleSum += b - a;
    }
  }

  private void add(TreeMap<Integer, Integer> map, int x) {
    map.merge(x, 1, Integer::sum);
  }

  private void remove(TreeMap<Integer, Integer> map, int x) {
    int c = map.get(x);
    if (c == 1) map.remove(x);
    else map.put(x, c - 1);
  }
}
